USE [tech_store];
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

MERGE dbo.categories AS target
USING (VALUES
    (N'dien-thoai', N'Điện thoại', 1),
    (N'laptop', N'Laptop', 2),
    (N'tablet', N'Tablet', 3),
    (N'dong-ho', N'Đồng hồ', 4),
    (N'phu-kien', N'Phụ kiện', 5)
) AS source(slug, name, sort_order) ON target.slug = source.slug
WHEN MATCHED THEN UPDATE SET name = source.name, sort_order = source.sort_order, is_active = 1
WHEN NOT MATCHED THEN INSERT (slug, name, sort_order) VALUES (source.slug, source.name, source.sort_order);

MERGE dbo.brands AS target
USING (VALUES
    (N'apple', N'Apple'),
    (N'samsung', N'Samsung'),
    (N'xiaomi', N'Xiaomi'),
    (N'anker', N'Anker'),
    (N'oppo', N'OPPO'),
    (N'asus', N'ASUS'),
    (N'lenovo', N'Lenovo'),
    (N'sony', N'Sony'),
    (N'logitech', N'Logitech'),
    (N'jbl', N'JBL'),
    (N'garmin', N'Garmin')
) AS source(slug, name) ON target.slug = source.slug
WHEN MATCHED THEN UPDATE SET name = source.name
WHEN NOT MATCHED THEN INSERT (slug, name) VALUES (source.slug, source.name);

DECLARE @seedProducts TABLE (
    slug VARCHAR(220) NOT NULL, category_slug VARCHAR(140) NOT NULL, brand_slug VARCHAR(140) NULL,
    name NVARCHAR(255) NOT NULL, short_description NVARCHAR(500) NULL, description NVARCHAR(MAX) NULL,
    price DECIMAL(13,2) NOT NULL, sale_price DECIMAL(13,2) NULL, stock_quantity INT NOT NULL,
    specifications NVARCHAR(MAX) NULL, main_image NVARCHAR(1000) NULL, is_featured BIT NOT NULL
);

INSERT INTO @seedProducts VALUES
    (N'iphone-16-pro-max', N'dien-thoai', N'apple', N'iPhone 16 Pro Max 256GB', N'Titan tự nhiên, camera Fusion 48MP', N'iPhone 16 Pro Max sở hữu màn hình Super Retina XDR 6,9 inch, chip A18 Pro mạnh mẽ và hệ thống camera Fusion 48MP. Nút Camera Control giúp ghi lại khoảnh khắc nhanh chóng; pin tối ưu cho cả ngày dài.', 34990000, 31990000, 14, N'{"Màn hình":"6,9 inch Super Retina XDR OLED, ProMotion 120Hz","Chip xử lý":"Apple A18 Pro","Camera sau":"Fusion 48MP + Ultra Wide 48MP + Telephoto 5x 12MP","Camera trước":"TrueDepth 12MP","Bộ nhớ":"256GB","Kết nối":"5G, Wi-Fi 7, USB-C","Chống nước":"IP68","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1592750475338-74b7b21085ab?auto=format&fit=crop&w=700&q=85', 1),
    (N'samsung-galaxy-s25-ultra', N'dien-thoai', N'samsung', N'Samsung Galaxy S25 Ultra 12GB/256GB', N'Galaxy AI, khung Titanium, camera 200MP', N'Galaxy S25 Ultra kết hợp màn hình Dynamic AMOLED 2X sắc nét, bút S Pen tích hợp và các công cụ Galaxy AI hỗ trợ công việc hằng ngày. Cụm camera đa tiêu cự linh hoạt cho ảnh chụp chi tiết.', 33990000, 29990000, 9, N'{"Màn hình":"6,9 inch Dynamic AMOLED 2X, 120Hz","Chip xử lý":"Snapdragon 8 Elite for Galaxy","Camera sau":"200MP + 50MP + 50MP + 10MP","RAM":"12GB","Bộ nhớ":"256GB","Pin":"5.000mAh, sạc nhanh 45W","Chống nước":"IP68","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?auto=format&fit=crop&w=700&q=85', 1),
    (N'macbook-air-m3', N'laptop', N'apple', N'MacBook Air 13 M3 8GB/256GB', N'Mỏng nhẹ, chip Apple M3, pin đến 18 giờ', N'MacBook Air M3 trong thiết kế mỏng nhẹ, vận hành êm ái không quạt. Màn hình Liquid Retina 13,6 inch, camera 1080p và thời lượng pin dài phù hợp học tập, làm việc linh hoạt.', 27990000, 23990000, 7, N'{"Màn hình":"13,6 inch Liquid Retina, 500 nit","Chip xử lý":"Apple M3, CPU 8 lõi, GPU 10 lõi","RAM":"8GB unified memory","Ổ cứng":"SSD 256GB","Pin":"Lên đến 18 giờ","Cổng kết nối":"MagSafe 3, 2 x Thunderbolt/USB 4","Trọng lượng":"1,24kg","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=700&q=85', 1),
    (N'ipad-air-m2', N'tablet', N'apple', N'iPad Air 11 inch M2 Wi-Fi 128GB', N'Chip M2, màn hình Liquid Retina 11 inch', N'iPad Air M2 có hiệu năng mạnh cho sáng tạo và giải trí, màn hình Liquid Retina 11 inch cùng camera trước đặt cạnh ngang tiện gọi video. Tương thích Apple Pencil Pro và Magic Keyboard.', 16990000, 14990000, 12, N'{"Màn hình":"11 inch Liquid Retina, True Tone","Chip xử lý":"Apple M2","Camera sau":"12MP Wide, quay video 4K","Camera trước":"12MP Center Stage","Bộ nhớ":"128GB","Kết nối":"Wi-Fi 6E, USB-C","Phụ kiện":"Hỗ trợ Apple Pencil Pro","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?auto=format&fit=crop&w=700&q=85', 1),
    (N'apple-watch-series-10', N'dong-ho', N'apple', N'Apple Watch Series 10 GPS 42mm', N'Thiết kế mỏng nhẹ, theo dõi sức khỏe toàn diện', N'Apple Watch Series 10 có màn hình lớn, góc nhìn rộng và thiết kế mỏng nhẹ. Theo dõi hoạt động, giấc ngủ, nhịp tim và nhận thông báo tiện lợi ngay trên cổ tay.', 11990000, 9990000, 20, N'{"Kích thước":"42mm","Màn hình":"Always-On Retina OLED góc rộng","Chất liệu vỏ":"Nhôm","Kết nối":"GPS, Bluetooth, Wi-Fi","Chống nước":"50m, chống bụi IP6X","Tính năng":"Theo dõi sức khỏe và giấc ngủ","Tương thích":"iPhone Xs trở lên","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=700&q=85', 1),
    (N'airpods-pro-2', N'phu-kien', N'apple', N'AirPods Pro 2 USB-C', N'Chống ồn chủ động, âm thanh không gian', N'AirPods Pro 2 sử dụng chip H2, chống ồn chủ động và chế độ Xuyên âm thích ứng. Hộp sạc USB-C hỗ trợ sạc không dây và có loa tích hợp để tìm kiếm.', 6190000, 4990000, 32, N'{"Chip":"Apple H2","Kết nối":"Bluetooth 5.3","Chống ồn":"Chủ động, Xuyên âm thích ứng","Cổng sạc":"USB-C, MagSafe, Qi","Thời lượng pin":"Lên đến 6 giờ mỗi lần sạc","Chống bụi/nước":"IP54","Tương thích":"Thiết bị Apple và Bluetooth","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1603351154351-5e2d0600bb77?auto=format&fit=crop&w=700&q=85', 1),
    (N'xiaomi-14t-pro', N'dien-thoai', N'xiaomi', N'Xiaomi 14T Pro 12GB/512GB', N'Camera Leica, Dimensity 9300+, sạc nhanh 120W', N'Xiaomi 14T Pro kết hợp hệ thống hình ảnh Leica, màn hình AMOLED 144Hz và hiệu năng Dimensity 9300+. Bộ nhớ lớn 512GB và sạc nhanh giúp máy sẵn sàng cho cả công việc lẫn giải trí.', 16990000, 14990000, 18, N'{"Màn hình":"6,67 inch AMOLED, 144Hz","Chip xử lý":"MediaTek Dimensity 9300+","Camera sau":"50MP Leica + 50MP Telephoto + 12MP Ultra Wide","RAM":"12GB","Bộ nhớ":"512GB","Pin":"5.000mAh, sạc nhanh 120W","Chống nước":"IP68","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1598327105666-5b89351aff97?auto=format&fit=crop&w=700&q=85', 1),
    (N'sac-anker-737', N'phu-kien', N'anker', N'Pin sạc dự phòng Anker 737 24000mAh', N'Dung lượng 24.000mAh, công suất sạc 140W', N'Pin sạc dự phòng Anker 737 cung cấp công suất lên đến 140W, màn hình hiển thị trạng thái pin và khả năng sạc đồng thời nhiều thiết bị.', 3990000, 2890000, 26, N'{"Dung lượng":"24.000mAh / 86,4Wh","Công suất tối đa":"140W","Cổng kết nối":"2 x USB-C, 1 x USB-A","Màn hình":"Digital Display","Tương thích":"Điện thoại, tablet, laptop USB-C","Bảo hành":"18 tháng chính hãng"}', N'https://images.unsplash.com/photo-1609091839311-d5365f9ff1c5?auto=format&fit=crop&w=700&q=85', 0),
    (N'iphone-16-128gb', N'dien-thoai', N'apple', N'iPhone 16 128GB', N'Chip A18, nút Camera Control, camera kép 48MP', N'iPhone 16 trang bị chip A18, nút Camera Control và camera Fusion 48MP. Màn hình Super Retina XDR 6,1 inch hiển thị sắc nét trong thiết kế bền bỉ.', 22990000, 19990000, 22, N'{"Màn hình":"6,1 inch Super Retina XDR OLED","Chip xử lý":"Apple A18","Camera sau":"Fusion 48MP + Ultra Wide 12MP","Bộ nhớ":"128GB","Kết nối":"5G, Wi-Fi 7, USB-C","Chống nước":"IP68","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1592750475338-74b7b21085ab?auto=format&fit=crop&w=700&q=85', 1),
    (N'samsung-galaxy-a56', N'dien-thoai', N'samsung', N'Samsung Galaxy A56 5G 8GB/256GB', N'Màn hình Super AMOLED 120Hz, camera 50MP', N'Galaxy A56 5G sở hữu màn hình Super AMOLED 120Hz, camera chống rung quang học 50MP và thiết kế kháng nước bụi IP67. Hỗ trợ các tính năng AI hữu ích.', 11990000, 10490000, 25, N'{"Màn hình":"6,7 inch Super AMOLED, 120Hz","Chip xử lý":"Exynos 1580","Camera sau":"50MP OIS + 12MP + 5MP","RAM":"8GB","Bộ nhớ":"256GB","Pin":"5.000mAh, sạc 45W","Chống nước":"IP67","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?auto=format&fit=crop&w=700&q=85', 1),
    (N'xiaomi-redmi-note-14-pro', N'dien-thoai', N'xiaomi', N'Xiaomi Redmi Note 14 Pro 5G 8GB/256GB', N'Camera 200MP OIS, màn hình AMOLED 1.5K', N'Redmi Note 14 Pro 5G mang đến camera 200MP có chống rung quang học, màn hình AMOLED độ phân giải 1.5K và dung lượng pin lớn cho ngày dài sử dụng.', 9490000, 8490000, 31, N'{"Màn hình":"6,67 inch AMOLED 1.5K, 120Hz","Chip xử lý":"MediaTek Dimensity 7300-Ultra","Camera chính":"200MP OIS","RAM":"8GB","Bộ nhớ":"256GB","Pin":"5.110mAh","Chống nước":"IP68","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1598327105666-5b89351aff97?auto=format&fit=crop&w=700&q=85', 0),
    (N'oppo-reno13-5g', N'dien-thoai', N'oppo', N'OPPO Reno13 5G 12GB/256GB', N'Chân dung AI, màn hình AMOLED 120Hz', N'OPPO Reno13 5G có thiết kế mỏng nhẹ, camera chân dung AI và màn hình AMOLED 120Hz. Máy hỗ trợ các công cụ chỉnh sửa ảnh tiện lợi ngay trên thiết bị.', 15990000, 13990000, 16, N'{"Màn hình":"6,59 inch AMOLED, 120Hz","Chip xử lý":"MediaTek Dimensity 8350","Camera sau":"50MP OIS + 8MP Ultra Wide","RAM":"12GB","Bộ nhớ":"256GB","Pin":"5.600mAh, sạc 80W","Chống nước":"IP68/IP69","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?auto=format&fit=crop&w=700&q=85', 0),
    (N'macbook-air-m4-13', N'laptop', N'apple', N'MacBook Air 13 M4 16GB/256GB', N'Chip M4, RAM 16GB, hỗ trợ hai màn hình ngoài', N'MacBook Air M4 cân bằng giữa tính di động và hiệu năng với RAM 16GB, camera 12MP Center Stage cùng khả năng kết nối hai màn hình ngoài.', 27990000, 26990000, 11, N'{"Màn hình":"13,6 inch Liquid Retina","Chip xử lý":"Apple M4, CPU 10 lõi","RAM":"16GB unified memory","Ổ cứng":"SSD 256GB","Camera":"12MP Center Stage","Cổng kết nối":"MagSafe 3, 2 x Thunderbolt 4","Trọng lượng":"1,24kg","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=700&q=85', 1),
    (N'asus-vivobook-15', N'laptop', N'asus', N'ASUS Vivobook 15 OLED Core i5 16GB/512GB', N'Màn OLED sống động, RAM 16GB, SSD 512GB', N'Vivobook 15 OLED dành cho học tập và văn phòng với màn hình OLED rực rỡ, bàn phím số tiện dụng và cấu hình đa nhiệm ổn định.', 18990000, 16990000, 8, N'{"Màn hình":"15,6 inch OLED Full HD","CPU":"Intel Core i5 thế hệ 13","RAM":"16GB DDR4","Ổ cứng":"SSD 512GB","Đồ họa":"Intel Iris Xe","Kết nối":"Wi-Fi 6E, USB-C, HDMI","Trọng lượng":"Khoảng 1,7kg","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1496181133206-80ce9b88a853?auto=format&fit=crop&w=700&q=85', 1),
    (N'lenovo-ideapad-slim-5', N'laptop', N'lenovo', N'Lenovo IdeaPad Slim 5 14 inch Ryzen 7 16GB/512GB', N'Ryzen 7, màn hình 2K, thiết kế nhôm gọn nhẹ', N'IdeaPad Slim 5 có thiết kế vỏ nhôm gọn nhẹ, màn hình độ phân giải cao và bộ xử lý Ryzen 7 cho các công việc văn phòng, học tập và đa nhiệm.', 19990000, 18490000, 10, N'{"Màn hình":"14 inch 2K IPS","CPU":"AMD Ryzen 7 8845HS","RAM":"16GB LPDDR5X","Ổ cứng":"SSD 512GB","Đồ họa":"AMD Radeon 780M","Pin":"57Wh","Kết nối":"Wi-Fi 6E, USB-C","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1496181133206-80ce9b88a853?auto=format&fit=crop&w=700&q=85', 0),
    (N'ipad-mini-a17-pro', N'tablet', N'apple', N'iPad mini A17 Pro Wi-Fi 128GB', N'Nhỏ gọn 8,3 inch, chip A17 Pro, Apple Pencil Pro', N'iPad mini có kích thước nhỏ gọn để mang theo, màn hình Liquid Retina 8,3 inch và chip A17 Pro đáp ứng tốt nhu cầu đọc, ghi chú và giải trí.', 13990000, 12990000, 13, N'{"Màn hình":"8,3 inch Liquid Retina","Chip xử lý":"Apple A17 Pro","Camera sau":"12MP Wide","Bộ nhớ":"128GB","Kết nối":"Wi-Fi 6E, USB-C","Phụ kiện":"Hỗ trợ Apple Pencil Pro","Trọng lượng":"293g","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?auto=format&fit=crop&w=700&q=85', 1),
    (N'samsung-galaxy-tab-s10-fe', N'tablet', N'samsung', N'Samsung Galaxy Tab S10 FE Wi-Fi 8GB/128GB', N'Màn hình 10,9 inch, đi kèm S Pen', N'Galaxy Tab S10 FE là tablet đa dụng với màn hình 10,9 inch, bút S Pen trong hộp và khả năng kháng nước bụi IP68.', 10990000, 9990000, 15, N'{"Màn hình":"10,9 inch LCD, 90Hz","Chip xử lý":"Exynos 1580","RAM":"8GB","Bộ nhớ":"128GB, hỗ trợ microSD","Camera sau":"13MP","Pin":"8.000mAh","Chống nước":"IP68","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?auto=format&fit=crop&w=700&q=85', 1),
    (N'xiaomi-pad-7', N'tablet', N'xiaomi', N'Xiaomi Pad 7 Wi-Fi 8GB/128GB', N'Màn hình 3.2K 144Hz, pin 8850mAh', N'Xiaomi Pad 7 kết hợp màn hình 3.2K tần số quét 144Hz, hệ thống bốn loa Dolby Atmos và pin dung lượng lớn phục vụ học tập, xem phim.', 9990000, 8990000, 19, N'{"Màn hình":"11,2 inch 3.2K, 144Hz","Chip xử lý":"Snapdragon 7+ Gen 3","RAM":"8GB","Bộ nhớ":"128GB","Pin":"8.850mAh, sạc 45W","Âm thanh":"4 loa Dolby Atmos","Kết nối":"Wi-Fi 6E, USB-C","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?auto=format&fit=crop&w=700&q=85', 0),
    (N'apple-watch-se-2', N'dong-ho', N'apple', N'Apple Watch SE 2 GPS 40mm', N'Theo dõi vận động, phát hiện té ngã, GPS', N'Apple Watch SE là lựa chọn gọn nhẹ để theo dõi vận động, nhận thông báo và giữ kết nối. Hỗ trợ phát hiện té ngã và SOS khẩn cấp.', 6990000, 5990000, 24, N'{"Kích thước":"40mm","Màn hình":"Retina OLED","Chip":"Apple S8","Kết nối":"GPS, Bluetooth, Wi-Fi","Chống nước":"50m","Tương thích":"iPhone Xs trở lên","Chất liệu":"Nhôm","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=700&q=85', 1),
    (N'samsung-galaxy-watch7', N'dong-ho', N'samsung', N'Samsung Galaxy Watch7 Bluetooth 44mm', N'Galaxy AI, GPS hai băng tần, theo dõi giấc ngủ', N'Galaxy Watch7 theo dõi sức khỏe và vận động với cảm biến BioActive thế hệ mới, GPS chính xác và nhiều mặt đồng hồ tùy biến.', 7990000, 6990000, 17, N'{"Kích thước":"44mm","Màn hình":"Super AMOLED 1,5 inch","Chip":"Exynos W1000","Bộ nhớ":"32GB","Kết nối":"Bluetooth, Wi-Fi, GPS","Chống nước":"5ATM + IP68","Tương thích":"Android 11 trở lên","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=700&q=85', 1),
    (N'sony-wh-1000xm5', N'phu-kien', N'sony', N'Tai nghe Sony WH-1000XM5 chống ồn', N'Chống ồn chủ động, pin nghe nhạc đến 30 giờ', N'Sony WH-1000XM5 trang bị chống ồn chủ động, micro đa hướng cho đàm thoại rõ ràng và đệm tai êm ái khi sử dụng lâu.', 8990000, 7290000, 12, N'{"Kiểu tai nghe":"Chụp tai không dây","Chống ồn":"Chủ động ANC","Kết nối":"Bluetooth 5.2, jack 3,5mm","Thời lượng pin":"Lên đến 30 giờ","Sạc":"USB-C, sạc nhanh","Micro":"Đa hướng","Trọng lượng":"Khoảng 250g","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=700&q=85', 1),
    (N'sac-anker-nano-65w', N'phu-kien', N'anker', N'Sạc Anker Nano 65W GaN 3 cổng', N'Công nghệ GaN, sạc nhanh laptop và điện thoại', N'Củ sạc Anker Nano 65W nhỏ gọn với công nghệ GaN, hai cổng USB-C và một USB-A, phù hợp sạc laptop, điện thoại và tablet.', 1290000, 990000, 40, N'{"Công suất tối đa":"65W","Cổng":"2 x USB-C, 1 x USB-A","Công nghệ":"GaN, Power Delivery","Điện áp":"100-240V","Tương thích":"Laptop USB-C, điện thoại, tablet","Bảo hành":"18 tháng chính hãng"}', N'https://images.unsplash.com/photo-1583394838336-acd977736f90?auto=format&fit=crop&w=700&q=85', 1),
    (N'logitech-mx-master-3s', N'phu-kien', N'logitech', N'Chuột Logitech MX Master 3S', N'Cuộn MagSpeed, cảm biến 8000 DPI, kết nối đa thiết bị', N'MX Master 3S là chuột công thái học cho công việc, có con lăn MagSpeed, thao tác yên tĩnh và kết nối chuyển đổi giữa tối đa ba thiết bị.', 2690000, 2190000, 21, N'{"Cảm biến":"Darkfield 200-8.000 DPI","Kết nối":"Bluetooth LE, Logi Bolt USB","Pin":"Sạc USB-C, dùng đến 70 ngày","Nút":"7 nút tùy chỉnh","Tương thích":"Windows, macOS, Linux, ChromeOS","Bảo hành":"12 tháng chính hãng"}', N'https://images.unsplash.com/photo-1527814050087-3793815479db?auto=format&fit=crop&w=700&q=85', 0),
    (N'loa-jbl-flip-6', N'phu-kien', N'jbl', N'Loa Bluetooth JBL Flip 6', N'Âm thanh JBL Original Pro, chống nước IP67', N'JBL Flip 6 là loa Bluetooth di động với âm thanh mạnh mẽ, thời lượng phát nhạc dài và khả năng chống bụi nước IP67.', 2990000, 2390000, 18, N'{"Công suất":"30W RMS","Kết nối":"Bluetooth 5.1","Thời lượng pin":"Lên đến 12 giờ","Chống nước":"IP67","Sạc":"USB-C","Tính năng":"JBL PartyBoost","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1608043152269-423dbba4e7e1?auto=format&fit=crop&w=700&q=85', 0),
    (N'samsung-990-evo-plus-1tb', N'phu-kien', N'samsung', N'SSD Samsung 990 EVO Plus 1TB NVMe', N'SSD NVMe PCIe 4.0, nâng cấp laptop và PC', N'Samsung 990 EVO Plus là SSD NVMe dung lượng 1TB, phù hợp nâng cấp dung lượng lưu trữ cho laptop và máy tính để bàn tương thích.', 2990000, 2490000, 14, N'{"Dung lượng":"1TB","Chuẩn giao tiếp":"M.2 NVMe PCIe 4.0 x4 / 5.0 x2","Kích thước":"M.2 2280","Đọc tuần tự tối đa":"Lên đến 7.250MB/s","Tương thích":"Máy có khe M.2 NVMe","Bảo hành":"5 năm hoặc theo TBW"}', N'https://images.unsplash.com/photo-1597872200969-2b65d56bd16b?auto=format&fit=crop&w=700&q=85', 0),
