    (N'samsung-galaxy-z-flip6', N'dien-thoai', N'samsung', N'Samsung Galaxy Z Flip6 12GB/256GB', N'Điện thoại gập nhỏ gọn, FlexWindow tiện dụng', N'Galaxy Z Flip6 kết hợp thiết kế gập linh hoạt với màn hình chính Dynamic AMOLED 2X và màn hình FlexWindow bên ngoài. Camera chính 50MP hỗ trợ chụp ảnh linh hoạt.', 28990000, 24990000, 8, N'{"Màn hình chính":"6,7 inch Dynamic AMOLED 2X","Màn hình ngoài":"3,4 inch Super AMOLED","Chip xử lý":"Snapdragon 8 Gen 3 for Galaxy","RAM":"12GB","Bộ nhớ":"256GB","Camera chính":"50MP OIS","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?auto=format&fit=crop&w=700&q=85', 1),
    (N'oppo-find-x8', N'dien-thoai', N'oppo', N'OPPO Find X8 5G 16GB/512GB', N'Camera Hasselblad, màn hình AMOLED 120Hz', N'OPPO Find X8 có màn hình AMOLED mượt mà, hệ thống camera đa tiêu cự và bộ nhớ 512GB rộng rãi cho ảnh, video và ứng dụng.', 22990000, 20990000, 11, N'{"Màn hình":"6,59 inch AMOLED, 120Hz","Chip xử lý":"MediaTek Dimensity 9400","RAM":"16GB","Bộ nhớ":"512GB","Camera sau":"Ba camera 50MP","Pin":"5630mAh, sạc nhanh","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1598327105666-5b89351aff97?auto=format&fit=crop&w=700&q=85', 1),
    (N'xiaomi-redmi-note-14-5g', N'dien-thoai', N'xiaomi', N'Xiaomi Redmi Note 14 5G 8GB/256GB', N'AMOLED 120Hz, camera độ phân giải cao', N'Redmi Note 14 5G là lựa chọn cân bằng cho nhu cầu hằng ngày với màn hình AMOLED 120Hz, kết nối 5G và bộ nhớ 256GB.', 7990000, 6990000, 28, N'{"Màn hình":"6,67 inch AMOLED, 120Hz","Chip xử lý":"MediaTek Dimensity 7025-Ultra","RAM":"8GB","Bộ nhớ":"256GB","Camera chính":"108MP","Kết nối":"5G, USB-C","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1598327105666-5b89351aff97?auto=format&fit=crop&w=700&q=85', 1),
    (N'asus-tuf-gaming-a15', N'laptop', N'asus', N'Laptop ASUS TUF Gaming A15 Ryzen 7/16GB/512GB', N'Laptop gaming mạnh mẽ, màn hình 144Hz', N'ASUS TUF Gaming A15 mang đến cấu hình hiệu năng cao cho học tập, làm việc và giải trí. Thiết kế bền bỉ, bàn phím có đèn nền và khả năng nâng cấp linh hoạt.', 26990000, 24990000, 6, N'{"Màn hình":"15,6 inch Full HD, 144Hz","Chip xử lý":"AMD Ryzen 7","RAM":"16GB","Ổ cứng":"SSD 512GB","Đồ họa":"NVIDIA GeForce RTX","Hệ điều hành":"Windows","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1496181133206-80ce9b88a853?auto=format&fit=crop&w=700&q=85', 1),
    (N'lenovo-loq-15', N'laptop', N'lenovo', N'Laptop Lenovo LOQ 15 16GB/512GB', N'Laptop hiệu năng cao cho game và sáng tạo', N'Lenovo LOQ 15 có màn hình lớn, hệ thống tản nhiệt tối ưu và cấu hình phù hợp chơi game, học tập kỹ thuật hoặc sáng tạo nội dung.', 23990000, 21990000, 9, N'{"Màn hình":"15,6 inch Full HD, 144Hz","Chip xử lý":"Intel Core i5","RAM":"16GB","Ổ cứng":"SSD 512GB","Đồ họa":"NVIDIA GeForce RTX","Bàn phím":"Có đèn nền","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1496181133206-80ce9b88a853?auto=format&fit=crop&w=700&q=85', 1),
