    (N'xiaomi-pad-7-pro', N'tablet', N'xiaomi', N'Xiaomi Pad 7 Pro Wi-Fi 8GB/256GB', N'Màn hình 3.2K 144Hz, giải trí và làm việc linh hoạt', N'Xiaomi Pad 7 Pro có màn hình độ phân giải cao, tần số quét mượt và hỗ trợ phụ kiện bàn phím, bút cảm ứng cho nhiều nhu cầu sử dụng.', 13990000, 12990000, 13, N'{"Màn hình":"11,2 inch, 3.2K, 144Hz","Chip xử lý":"Snapdragon 8s Gen 3","RAM":"8GB","Bộ nhớ":"256GB","Camera sau":"50MP","Kết nối":"Wi-Fi, USB-C","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?auto=format&fit=crop&w=700&q=85', 1),
    (N'ipad-10-64gb', N'tablet', N'apple', N'iPad 10 Wi-Fi 64GB', N'Liquid Retina 10,9 inch, thiết kế nhiều màu', N'iPad thế hệ 10 sở hữu màn hình Liquid Retina 10,9 inch, camera trước đặt cạnh ngang và cổng USB-C, phù hợp học tập và giải trí.', 9990000, 8990000, 15, N'{"Màn hình":"10,9 inch Liquid Retina","Chip xử lý":"Apple A14 Bionic","Bộ nhớ":"64GB","Camera sau":"12MP Wide","Kết nối":"Wi-Fi 6, USB-C","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?auto=format&fit=crop&w=700&q=85', 1),
    (N'garmin-forerunner-165', N'dong-ho', N'garmin', N'Đồng hồ Garmin Forerunner 165', N'Màn hình AMOLED, GPS và chế độ luyện tập chạy bộ', N'Garmin Forerunner 165 hỗ trợ theo dõi vận động, GPS và các chỉ số tập luyện trong thiết kế nhẹ, phù hợp cho người yêu chạy bộ.', 6990000, 6490000, 10, N'{"Màn hình":"AMOLED cảm ứng","Định vị":"GPS đa hệ thống","Tính năng":"Theo dõi sức khỏe và luyện tập","Kết nối":"Bluetooth, ANT+","Chống nước":"5 ATM","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=700&q=85', 1),
    (N'xiaomi-smart-band-9-pro', N'dong-ho', N'xiaomi', N'Vòng đeo tay Xiaomi Smart Band 9 Pro', N'Màn hình AMOLED lớn, theo dõi hoạt động cả ngày', N'Xiaomi Smart Band 9 Pro hỗ trợ theo dõi vận động, giấc ngủ và thông báo, thiết kế nhẹ để đeo thoải mái trong ngày.', 2190000, 1890000, 24, N'{"Màn hình":"AMOLED màu","Theo dõi":"Nhịp tim, giấc ngủ, vận động","Định vị":"GPS tích hợp","Chống nước":"5 ATM","Kết nối":"Bluetooth","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=700&q=85', 1),
    (N'anker-soundcore-liberty-4-nc', N'phu-kien', N'anker', N'Tai nghe Anker Soundcore Liberty 4 NC', N'Tai nghe true wireless chống ồn chủ động', N'Soundcore Liberty 4 NC mang đến chống ồn chủ động, kết nối Bluetooth đa thiết bị và hộp sạc nhỏ gọn cho nhu cầu nghe nhạc hằng ngày.', 2490000, 1990000, 27, N'{"Kiểu tai nghe":"True wireless","Chống ồn":"Chủ động ANC","Kết nối":"Bluetooth 5.3","Thời lượng pin":"Tối đa khoảng 10 giờ mỗi lần sạc","Sạc":"USB-C, sạc không dây","Bảo hành":"18 tháng chính hãng"}', N'https://images.unsplash.com/photo-1603351154351-5e2d0600bb77?auto=format&fit=crop&w=700&q=85', 1),
    (N'logitech-g-pro-x-superlight', N'phu-kien', N'logitech', N'Chuột gaming Logitech G Pro X Superlight', N'Chuột gaming không dây siêu nhẹ', N'Logitech G Pro X Superlight là chuột gaming không dây thiết kế nhẹ, cảm biến chính xác và kết nối không dây độ trễ thấp.', 2990000, 2590000, 12, N'{"Cảm biến":"HERO","Độ phân giải":"Lên đến 25.600 DPI","Kết nối":"LIGHTSPEED không dây","Trọng lượng":"Dưới 63g","Pin":"Sạc USB","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1527814050087-3793815479db?auto=format&fit=crop&w=700&q=85', 1),
    (N'jbl-tune-770nc', N'phu-kien', N'jbl', N'Tai nghe chụp tai JBL Tune 770NC', N'Chống ồn thích ứng, pin nghe nhạc dài', N'JBL Tune 770NC là tai nghe chụp tai không dây với chống ồn chủ động, kết nối đa điểm và thiết kế gập gọn.', 2990000, 2490000, 16, N'{"Kiểu tai nghe":"Chụp tai không dây","Chống ồn":"Chủ động ANC","Kết nối":"Bluetooth 5.3, jack 3,5mm","Thời lượng pin":"Tối đa 70 giờ (tắt ANC)","Sạc":"USB-C","Bảo hành":"Bảo hành chính hãng 12 tháng"}', N'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=700&q=85', 1),
    (N'samsung-t7-shield-1tb', N'phu-kien', N'samsung', N'SSD di động Samsung T7 Shield 1TB', N'Ổ cứng SSD di động nhỏ gọn, kết nối USB-C', N'Samsung T7 Shield là ổ SSD di động dung lượng 1TB, thích hợp sao lưu dữ liệu và mang theo khi làm việc.', 3990000, 3490000, 9, N'{"Dung lượng":"1TB","Kết nối":"USB 3.2 Gen 2, USB-C","Tốc độ đọc":"Tối đa 1.050MB/s","Tốc độ ghi":"Tối đa 1.000MB/s","Tương thích":"Windows, macOS, Android","Bảo hành":"3 năm chính hãng"}', N'https://images.unsplash.com/photo-1597872200969-2b65d56bd16b?auto=format&fit=crop&w=700&q=85', 1);

INSERT INTO dbo.products
    (category_id, brand_id, slug, name, short_description, description, price, sale_price, stock_quantity, specifications, main_image, is_featured)
SELECT c.id, b.id, seed.slug, seed.name, seed.short_description, seed.description, seed.price, seed.sale_price, seed.stock_quantity, seed.specifications, seed.main_image, seed.is_featured
FROM @seedProducts AS seed
JOIN dbo.categories AS c ON c.slug = seed.category_slug
LEFT JOIN dbo.brands AS b ON b.slug = seed.brand_slug
WHERE NOT EXISTS (SELECT 1 FROM dbo.products AS existing WHERE existing.slug = seed.slug);

INSERT INTO dbo.product_images (product_id, image_url, alt_text, sort_order)
SELECT p.id, p.main_image, p.name, 0
FROM dbo.products AS p
JOIN @seedProducts AS seed ON seed.slug = p.slug
WHERE p.main_image IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM dbo.product_images AS image WHERE image.product_id = p.id AND image.image_url = p.main_image);

IF NOT EXISTS (SELECT 1 FROM dbo.product_variants WHERE sku = 'IPHONE16PM-256-NAT')
    INSERT INTO dbo.product_variants (product_id, sku, color, storage, price_adjustment, stock_quantity)
    SELECT id, 'IPHONE16PM-256-NAT', N'Titan t? nhi?n', N'256GB', 0, 8 FROM dbo.products WHERE slug = 'iphone-16-pro-max';
IF NOT EXISTS (SELECT 1 FROM dbo.product_variants WHERE sku = 'IPHONE16PM-256-BLK')
    INSERT INTO dbo.product_variants (product_id, sku, color, storage, price_adjustment, stock_quantity)
    SELECT id, 'IPHONE16PM-256-BLK', N'Titan ?en', N'256GB', 0, 6 FROM dbo.products WHERE slug = 'iphone-16-pro-max';
IF NOT EXISTS (SELECT 1 FROM dbo.product_variants WHERE sku = 'S25U-256-TITANIUM')
    INSERT INTO dbo.product_variants (product_id, sku, color, storage, price_adjustment, stock_quantity)
    SELECT id, 'S25U-256-TITANIUM', N'Titanium Gray', N'256GB', 0, 9 FROM dbo.products WHERE slug = 'samsung-galaxy-s25-ultra';

COMMIT TRANSACTION;
